import { NextRequest, NextResponse } from "next/server";
import { getCurrentUser } from "@/lib/auth";
import { generateInvoicePdfBuffer } from "@/lib/billing/invoice-pdf";
import { getCustomerInvoice, getCustomerInvoiceHtml } from "@/server/billing/invoice.service";

export const runtime = "nodejs";

export async function GET(req: NextRequest, { params }: { params: Promise<{ id: string }> }) {
  const user = await getCurrentUser();
  const customerUid = user?.customerUid;

  if (!user || !customerUid) {
    return NextResponse.json({ error: "Login required." }, { status: 401 });
  }

  const { id } = await params;
  const format = new URL(req.url).searchParams.get("format") || "html";

  if (format === "pdf") {
    const invoice = await getCustomerInvoice(customerUid, id);
    if (!invoice) return NextResponse.json({ error: "Invoice not found." }, { status: 404 });

    const pdf = await generateInvoicePdfBuffer(invoice);
    return new NextResponse(new Uint8Array(pdf), {
      headers: {
        "Content-Type": "application/pdf",
        "Content-Disposition": `attachment; filename="invoice-${invoice.invoice_number || id}.pdf"`,
      },
    });
  }

  const html = await getCustomerInvoiceHtml(customerUid, id);
  if (!html) return NextResponse.json({ error: "Invoice not found." }, { status: 404 });

  return new NextResponse(html, {
    headers: {
      "Content-Type": "text/html; charset=utf-8",
      "Content-Disposition": `inline; filename="invoice-${id}.html"`,
    },
  });
}
